from .api_base import API_base 

class NewAddress(API_base):
    """
    Generates a new Ethereum address that can be used to send or receive funds. Do not lose the password! We can't restore access to an address if you lose it.
    """
    def __init__(self):
        pass

    def execute(self, **params):
        expected_params = set(["p_password"])
        unexpected_params = set(params.keys()) - expected_params 
        if unexpected_params:
            return self.handle_error(f"Unexpected parameters: {', '.join(unexpected_params)}", 400)
        p_password = params.get('p_password', None)
        if p_password is None:
            return self.handle_error(f"Required parameter 'p_password' is missing", 400)
        is_valid, error = self.validate_type(p_password, 'p_password', str)
        if not is_valid:
            return error
        
        return {
            "status_code": 200, 
            "results": {
                "function_name": "NewAddress",
                "p_password": p_password
            }
        }

class Market_Trends_API(API_base):
    """
    Get the latest market trends and relevant news for a specified country and language.
    """
    def __init__(self):
        pass

    def execute(self, **params):
        expected_params = set(["p_trend_type", "p_country", "p_language"])
        unexpected_params = set(params.keys()) - expected_params 
        if unexpected_params:
            return self.handle_error(f"Unexpected parameters: {', '.join(unexpected_params)}", 400)
        p_trend_type = params.get('p_trend_type', None)
        if p_trend_type is None:
            return self.handle_error(f"Required parameter 'p_trend_type' is missing", 400)
        is_valid, error = self.validate_type(p_trend_type, 'p_trend_type', str)
        if not is_valid:
            return error
        
        if p_trend_type is not None and p_trend_type not in ["MARKET_INDEXES", "MOST_ACTIVE", "GAINERS", "LOSERS", "CRYPTO", "CURRENCIES", "CLIMATE_LEADERS"]:
            return self.handle_error(f"Parameter 'p_trend_type' not in valid enum", 400)
        
        p_country = params.get('p_country', "us")
        if p_country is not None:
            is_valid, error = self.validate_type(p_country, 'p_country', str)
            if not is_valid:
                return error
        
        p_language = params.get('p_language', "en")
        if p_language is not None:
            is_valid, error = self.validate_type(p_language, 'p_language', str)
            if not is_valid:
                return error
        
        return {
            "status_code": 200, 
            "results": {
                "function_name": "Market_Trends_API",
                "p_trend_type": p_trend_type,
                "p_country": p_country,
                "p_language": p_language
            }
        }

