class Abandoned_Baby_Indicator(API_base):
    """
    Retrieve historical data for the Abandoned Baby indicator for a specific cryptocurrency and exchange.
    """
    def __init__(self):
        pass

    def execute(self, **params):
        expected_params = set(["p_market", "p_interval", "p_exchange", "p_symbol", "p_backtracks", "p_from"])
        unexpected_params = set(params.keys()) - expected_params 
        if unexpected_params:
            return self.handle_error(f"Unexpected parameters: {', '.join(unexpected_params)}", 400)
        p_market = params.get('p_market', None)
        if p_market is None:
            return self.handle_error(f"Required parameter 'p_market' is missing", 400)
        is_valid, error = self.validate_type(p_market, 'p_market', str)
        if not is_valid:
            return error
        
        if p_market is not None and p_market not in ["spot", "usdt-perpetual", "inverse-perpetual"]:
            return self.handle_error(f"Parameter 'p_market' not in valid enum", 400)
        
        p_interval = params.get('p_interval', None)
        if p_interval is None:
            return self.handle_error(f"Required parameter 'p_interval' is missing", 400)
        is_valid, error = self.validate_type(p_interval, 'p_interval', str)
        if not is_valid:
            return error
        
        p_exchange = params.get('p_exchange', None)
        if p_exchange is None:
            return self.handle_error(f"Required parameter 'p_exchange' is missing", 400)
        is_valid, error = self.validate_type(p_exchange, 'p_exchange', str)
        if not is_valid:
            return error
        
        p_symbol = params.get('p_symbol', None)
        if p_symbol is None:
            return self.handle_error(f"Required parameter 'p_symbol' is missing", 400)
        is_valid, error = self.validate_type(p_symbol, 'p_symbol', str)
        if not is_valid:
            return error
        
        _default_p_backtracks = float(1.0) if 1.0 != "" else 0.0
        p_backtracks = params.get('p_backtracks', _default_p_backtracks)
        if p_backtracks is not None:
            is_valid, error = self.validate_type(p_backtracks, 'p_backtracks', (float, int))
            if not is_valid:
                return error
        if p_backtracks is not None:
            p_backtracks = float(p_backtracks)
        
        p_from = params.get('p_from', "1683895800")
        if p_from is not None:
            is_valid, error = self.validate_type(p_from, 'p_from', str)
            if not is_valid:
                return error
        
        return {
            "status_code": 200, 
            "results": {
                "function_name": "Abandoned_Baby_Indicator",
                "p_market": p_market,
                "p_interval": p_interval,
                "p_exchange": p_exchange,
                "p_symbol": p_symbol,
                "p_backtracks": p_backtracks,
                "p_from": p_from
            }
        }

